import{_ as p,a0 as l,w as d,s as o,ao as r,I as t,x as a,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"命令列小技巧：讀取文件的不同方式 | LCTT x X-CMD","titleTemplate":false,"description":"命令列小技巧：讀取文件的不同方式 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列小技巧：讀取文件的不同方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列小技巧：讀取文件的不同方式 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20181012 Command line quick tips- Reading files different ways","title":"命令列小技巧：讀取文件的不同方式","tag":"201810","desc":""},"relativePath":"201810/20181012 Command line quick tips- Reading files different ways.md","filePath":"[post].md"}'),c={name:"201810/20181012 Command line quick tips- Reading files different ways.md"};function h(g,s,f,k,u,b){const e=l("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="命令列小技巧-讀取文件的不同方式" tabindex="-1">命令列小技巧：讀取文件的不同方式 <a class="header-anchor" href="#命令列小技巧-讀取文件的不同方式" aria-label="Permalink to “命令列小技巧：讀取文件的不同方式”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/10/commandlinequicktips-816x345.jpg" alt=""></p><p>作為圖形操作系統，Fedora 的使用是令人愉快的。你可以輕鬆地點擊完成任何任務。但你可能已經看到了，在底層還有一個強大的命令列。想要在 shell 下體驗，只需要在 Fedora 系統中打開你的終端應用。這篇文章是向你展示常見的命令列使用方法的系列文章之一。</p><p>在這部分，你將學習如何以不同的方式讀取文件，如果你在系統中打開一個終端完成一些工作，你就有可能需要讀取一兩個文件。</p><h3 id="一應俱全的大餐" tabindex="-1">一應俱全的大餐 <a class="header-anchor" href="#一應俱全的大餐" aria-label="Permalink to “一應俱全的大餐”">​</a></h3><p>對命令列終端的用户來説， <code>cat</code> 命令眾所周知。 當你 <code>cat</code> 一個文件，你很容易的把整個文件內容展示在你的屏幕上。而真正發生在底層的是文件一次讀取一行，然後一行一行寫入屏幕。</p><p>假設你有一個文件，叫做 <code>myfile</code>， 這個文件每行只有一個單詞。為了簡單起見，每行的單詞就是這行的行號，就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>one</span></span>
<span class="line"><span>two</span></span>
<span class="line"><span>three</span></span>
<span class="line"><span>four</span></span>
<span class="line"><span>five</span></span></code></pre></div><p>所以如果你 <code>cat</code> 這個文件，你就會看到如下輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat myfile</span></span>
<span class="line"><span>one</span></span>
<span class="line"><span>two</span></span>
<span class="line"><span>three</span></span>
<span class="line"><span>four</span></span>
<span class="line"><span>five</span></span></code></pre></div><p>並沒有太驚喜，不是嗎？ 但是有個有趣的轉折，只要使用 <code>tac</code> 命令，你可以從後往前 <code>cat</code> 這個文件。（請注意， Fedora 對這種有爭議的幽默不承擔任何責任！）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tac myfile</span></span>
<span class="line"><span>five</span></span>
<span class="line"><span>four</span></span>
<span class="line"><span>three</span></span>
<span class="line"><span>two</span></span>
<span class="line"><span>one</span></span></code></pre></div><p><code>cat</code> 命令允許你以不同的方式裝飾輸出，比如，你可以輸出行號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat -n myfile</span></span>
<span class="line"><span>     1 one</span></span>
<span class="line"><span>     2 two</span></span>
<span class="line"><span>     3 three</span></span>
<span class="line"><span>     4 four</span></span>
<span class="line"><span>     5 five</span></span></code></pre></div><p>還有其他選項可以顯示特殊字符和其他功能。要了解更多, 請運行 <code>man cat</code> 命令， 看完之後，按 <code>q</code> 即可退出回到 shell。</p><h3 id="挑選你的食物" tabindex="-1">挑選你的食物 <a class="header-anchor" href="#挑選你的食物" aria-label="Permalink to “挑選你的食物”">​</a></h3><p>通常，文件太長會無法全部顯示在屏幕上，您可能希望能夠像文檔一樣查看它。 這種情況下，可以試試 <code>less</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ less myfile</span></span></code></pre></div><p>你可以用方向鍵，也可以用 <code>PgUp</code>/<code>PgDn</code> 來查看文件， 按 <code>q</code> 就可以退回到 shell。</p><p>實際上，還有一個 <code>more</code> 命令，其基於老式的 UNIX 系統命令。如果在退回 shell 後仍想看到該文件的內容，則可能需要使用它。而 <code>less</code> 命令則讓你回到你離開 shell 之前的樣子，並且清除屏幕上你看到的所有的文件內容。</p><h3 id="一點披薩或甜點" tabindex="-1">一點披薩或甜點 <a class="header-anchor" href="#一點披薩或甜點" aria-label="Permalink to “一點披薩或甜點”">​</a></h3><p>有時，你所需的輸出只是文件的開頭。 比如，有一個非常長的文件，當你使用 <code>cat</code> 命令時，會顯示這個文件所有內容，前幾行的內容很容易滾動過去，導致你看不到。<code>head</code> 命令會幫你獲取文件的前幾行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ head -n 2 myfile</span></span>
<span class="line"><span>one</span></span>
<span class="line"><span>two</span></span></code></pre></div><p>同樣，你會用 <code>tail</code> 命令來查看文件的末尾幾行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tail -n 3 myfile</span></span>
<span class="line"><span>three</span></span>
<span class="line"><span>four</span></span>
<span class="line"><span>five</span></span></code></pre></div><p>當然，這些只是在這個領域的幾個簡單的命令。但它們可以讓你在閲讀文件時容易入手。</p><hr>`,27)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://fedoramagazine.org/commandline-quick-tips-reading-files-different-ways/"},{default:i(()=>[...s[0]||(s[0]=[a("https://fedoramagazine.org/commandline-quick-tips-reading-files-different-ways/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),n(e,{href:"https://fedoramagazine.org/author/pfrields/"},{default:i(()=>[...s[2]||(s[2]=[a("Paul W. Frields",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),n(e,{href:"https://github.com/distant1219"},{default:i(()=>[...s[4]||(s[4]=[a("distant1219",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const x=p(c,[["render",h]]);export{C as __pageData,x as default};
